(function(){
  const MAP_DATA="assets/world-map.png";
  const NS="http://www.w3.org/2000/svg";

  const spots=[
    /* ROUTES / PATHS — centered on the visible gold waypoint circles */
    {name:"Cinderfall Tarn",x:378,y:320,r:18,hitR:27,kind:"Route"},
    {name:"Ember Pass",x:378,y:484,r:18,hitR:27,kind:"Route"},
    {name:"Quarry Road",x:663,y:484,r:18,hitR:27,kind:"Route"},
    {name:"Frostpeak Climb",x:787,y:255,r:18,hitR:27,kind:"Route"},
    {name:"Snowline Rise",x:787,y:353,r:18,hitR:27,kind:"Route"},
    {name:"Glimmer Flats",x:951,y:484,r:18,hitR:27,kind:"Route"},
    {name:"Spark Woods",x:1039,y:483,r:18,hitR:27,kind:"Route"},
    {name:"Shade Trail",x:1287,y:483,r:18,hitR:27,kind:"Route"},
    {name:"Marsh Route",x:787,y:642,r:18,hitR:27,kind:"Route"},
    {name:"Coast Route",x:519,y:750,r:18,hitR:27,kind:"Route"},
    {name:"Softglade Path",x:302,y:817,r:18,hitR:27,kind:"Route"},
    {name:"Firstlight Village",x:301,y:921,r:18,hitR:27,kind:"Village"},

    /* TOWNS / CITIES — centered on the visible elemental emblems */
    {name:"Frostpeak",x:790,y:87,r:43,hitR:43,kind:"City",type:"Ice"},
    {name:"Emberfall",x:171,y:484,r:43,hitR:43,kind:"City",type:"Fire"},
    {name:"Stonereach",x:544,y:484,r:43,hitR:43,kind:"City",type:"Rock"},
    {name:"Spark Metropolis",x:790,y:484,r:45,hitR:45,kind:"City",type:"Electric"},
    {name:"Prismgate",x:1160,y:484,r:43,hitR:43,kind:"City",type:"Fairy"},
    {name:"Shadeholt",x:1411,y:484,r:43,hitR:43,kind:"City",type:"Dark"},
    {name:"Bloomvale",x:301,y:689,r:43,hitR:43,kind:"City",type:"Grass"},
    {name:"Tidemarsh",x:790,y:741,r:45,hitR:45,kind:"City",type:"Water"},
    {name:"The Spire",x:1249,y:877,r:46,hitR:46,kind:"Landmark"}
  ];


  const destinationImages={
    "Firstlight Village":"https://lumena.gg/images/destinations/firstlight-village.webp",
    "Bloomvale":"https://lumena.gg/images/destinations/bloomvale.webp",
    "Tidemarsh":"https://lumena.gg/images/destinations/tidemarsh-city.webp",
    "Spark Metropolis":"https://lumena.gg/images/destinations/spark-metropolis.webp",
    "Stonereach":"https://lumena.gg/images/destinations/stonereach-city.webp",
    "Emberfall":"https://lumena.gg/images/destinations/emberfell-town.webp",
    "Frostpeak":"https://lumena.gg/images/destinations/frostpeak-city.webp",
    "Prismgate":"https://lumena.gg/images/destinations/prismgate-city.webp",
    "Shadeholt":"https://lumena.gg/images/destinations/shadeholt-town.webp",
    "The Spire":"https://lumena.gg/images/destinations/the-spire.webp"
  };


  const locationNavOrder = ['Firstlight Village', 'Softglade Path', 'Bloomvale', 'Coast Route', 'Tidemarsh', 'Marsh Route', 'Spark Metropolis', 'Quarry Road', 'Stonereach', 'Emberpass', 'Cinderfall Tarn', 'Emberfall', 'Snowline Rise', 'Frostpeak Climb', 'Frostpeak', 'Glimmer Flats', 'Spark Woods', 'Prismgate', 'Shade Trail', 'Shadeholt', 'The Spire'];

  function navCanonicalName(name){
    const aliases={'Ember Pass': 'Emberpass', 'Tidemarsh City': 'Tidemarsh'};
    return aliases[name] || name;
  }

  function locationCategory(spot){
    if(!spot) return "route";
    const k=String(spot.kind||"").toLowerCase();
    return /town|city|landmark/.test(k) ? "town" : "route";
  }

  function findSpotForNavName(name){
    const wanted=navCanonicalName(name);
    return spots.find(s=>navCanonicalName(s.name)===wanted) || null;
  }

  function currentNavIndex(){
    const current=document.querySelector("#rebuilt-map-hotspots .map-dot.active");
    if(!current) return -1;
    const currentName=navCanonicalName(current.dataset.location||"");
    return locationNavOrder.findIndex(n=>navCanonicalName(n)===currentName);
  }

  function openLocationByNavIndex(index){
    if(!locationNavOrder.length) return;
    const wrapped=(index+locationNavOrder.length)%locationNavOrder.length;
    const targetName=locationNavOrder[wrapped];
    const target=findSpotForNavName(targetName);
    if(!target) return;
    const g=[...document.querySelectorAll("#rebuilt-map-hotspots .map-dot")]
      .find(n=>navCanonicalName(n.dataset.location||"")===navCanonicalName(target.name));
    if(g) showLocation(target,g);
  }

  const descriptions={
    "Firstlight Village":"A peaceful village where many journeys begin. Surrounded by open grasslands and gentle wilderness, Firstlight is a welcoming home for new Tamers and curious Lumen alike.",
    "Bloomvale":"A flourishing city nestled among lush forests and flower-filled meadows. Bloomvale thrives in harmony with nature, with Grass Lumen commonly found throughout the surrounding wilds.",
    "Tidemarsh":"A waterside city built where winding rivers, wetlands, and the sea meet. Its waterways shape everyday life, making Tidemarsh a natural gathering place for Water Lumen.",
    "Spark Metropolis":"A brilliant city alive with energy and invention. Towers and illuminated streets dominate the skyline while Electric Lumen thrive amid the constant pulse of the metropolis.",
    "Stonereach":"A rugged city standing between rocky highlands and volcanic territory. Built upon ancient stone, Stonereach is known for its imposing architecture and the Rock Lumen inhabiting the surrounding terrain.",
    "Emberfall":"A fiery settlement forged beside Lumena's volcanic lands. Rivers of molten rock illuminate the horizon, while Fire Lumen flourish in the intense heat surrounding the town.",
    "Frostpeak":"A remote city high among snow-covered mountains. Bitter winds and frozen paths make the journey difficult, but Ice Lumen have made this beautiful frozen region their home.",
    "Prismgate":"A radiant city hidden beyond enchanted woodland. Strange lights shimmer through the surrounding forests, giving Prismgate an almost dreamlike atmosphere favored by Fairy Lumen.",
    "Shadeholt":"A mysterious settlement standing beneath the shadow of the eastern wilderness. Its dark forests and quiet paths create an eerie refuge where Dark Lumen are commonly encountered.",
    "The Spire":"A mysterious tower rising from an isolated island far from the mainland. Few know its true purpose, and its lonely position has made the Spire one of Lumena's most intriguing landmarks.",

    "Softglade Path":"A gentle woodland trail connecting Firstlight Village to Bloomvale. Sunlight filters through the trees, and its calm grassy clearings make it a familiar route for beginning Tamers.",
    "Coast Route":"A breezy coastal road stretching between Bloomvale and Tidemarsh. Waves crash against the shoreline beside the path, drawing Lumen that favor open fields, beaches, and nearby waters.",
    "Marsh Route":"A damp trail winding north from Tidemarsh through wetlands and shallow waterways. Mist often hangs over the reeds, creating a rich habitat for Lumen adapted to marshy terrain.",
    "Glimmer Flats":"A wide, shimmering plain east of Spark Metropolis where mineral-rich ground catches the light. The open landscape gives wandering Lumen plenty of room to roam.",
    "Spark Woods":"An energized forest where faint electrical currents seem to hum through the trees. Strange flashes can be seen between the branches, making the woods feel alive even after sunset.",
    "Shade Trail":"A quiet path leading toward Shadeholt through darkened woodland. Thick canopies block much of the daylight, and cautious travelers often hear Lumen moving just beyond the trail.",
    "Ember Pass":"A scorched passage between Emberfall and Stonereach beneath the shadow of Cinderfall Tarn. Heat rises from cracked stone while volcanic winds sweep across the route.",
    "Cinderfall Tarn":"A volcanic crater lake suspended above Ember Pass. Dark water, black stone, and glowing fissures surround the tarn, creating one of the harshest encounter areas in western Lumena.",
    "Snowline Rise":"A steep ascent marking the point where green terrain gives way to snow and ice. Temperatures fall quickly here, and only hardy Lumen remain active along the exposed path.",
    "Frostpeak Climb":"The final mountain trail leading toward Frostpeak. Narrow icy paths, heavy snow, and bitter winds make the climb difficult, but rare cold-weather Lumen can be found along the way."
  };

  function norm(v){
    return String(v||"").toLowerCase().replace(/[^a-z0-9]+/g,"");
  }
  function getMapEncounterProbability(item){
    const id=String(item && item.dataset ? (item.dataset.id||"") : "");
    if(!id) return null;
    const detail=document.querySelector('.detail-view[data-id="'+CSS.escape(id)+'"]');
    if(!detail) return null;
    const probabilityLabel=[...detail.querySelectorAll('dt')].find(dt=>
      String(dt.textContent||'').trim().toLowerCase()==='probability'
    );
    if(!probabilityLabel || !probabilityLabel.nextElementSibling) return null;
    const value=parseFloat(String(probabilityLabel.nextElementSibling.textContent||'').replace('%','').trim());
    return Number.isFinite(value) ? value : null;
  }
  function locationItems(name){
    const target=norm(name);

    /* Sort the ACTIVE rebuilt World Map panel itself by each Lumen's actual
       encounter Probability value. The earlier sorter only affected the older
       route-results grid, so this newer town/route panel was still showing
       sidebar/Codex order. Unknown/missing probabilities are placed last. */
    function actualProbability(item){
      const id=String(item && item.dataset ? (item.dataset.id||"") : "");
      if(!id) return -Infinity;
      const detail=document.querySelector('.detail-view[data-id="'+CSS.escape(id)+'"]');
      if(!detail) return -Infinity;
      const probabilityLabel=[...detail.querySelectorAll('dt')].find(dt=>
        String(dt.textContent||'').trim().toLowerCase()==='probability'
      );
      if(!probabilityLabel || !probabilityLabel.nextElementSibling) return -Infinity;
      const value=parseFloat(String(probabilityLabel.nextElementSibling.textContent||'').replace('%','').trim());
      return Number.isFinite(value) ? value : -Infinity;
    }

    return [...document.querySelectorAll("#sidebar .side-item")].filter(item=>{
      return String(item.dataset.locations||"").split("|").some(loc=>norm(loc)===target);
    }).sort((a,b)=>{
      const pa=actualProbability(a), pb=actualProbability(b);
      if(pb!==pa) return pb-pa;
      return Number(a.dataset.num||9999)-Number(b.dataset.num||9999);
    });
  }
  function svg(tag,attrs){
    const n=document.createElementNS(NS,tag);
    Object.entries(attrs||{}).forEach(([k,v])=>n.setAttribute(k,String(v)));
    return n;
  }

  function closePanel(){
    const panel=document.getElementById("rebuilt-panel-card");
    if(!panel) return;
    panel.classList.add("panel-empty-state");
    panel.innerHTML='<div class="rebuilt-panel-empty">Click one of the gold circular markers on the map to view the Lumen recorded at that location.</div>';
    document.querySelectorAll("#rebuilt-map-hotspots .map-dot").forEach(g=>g.classList.remove("active"));
  }

  function openCodexItem(original){
    closeMap();
    setTimeout(()=>original.click(),0);
  }

  const headerTownEmblems = {"Emberfall": "data:image/png;base64,", "Stonereach": "data:image/png;base64,", "Frostpeak": "data:image/png;base64,", "Prismgate": "data:image/png;base64,", "Spark Metropolis": "data:image/png;base64,", "Tidemarsh": "data:image/png;base64,", "Bloomvale": "data:image/png;base64,", "Shadeholt": "data:image/png;base64,", "The Spire": "data:image/png;base64,"};

  function showLocation(spot,g){
    document.querySelectorAll("#rebuilt-map-hotspots .map-dot").forEach(n=>n.classList.toggle("active",n===g));
    const panel=document.getElementById("rebuilt-panel-card");
    const items=locationItems(spot.name);
    panel.classList.remove("panel-empty-state");
    panel.innerHTML="";

    const head=document.createElement("div");
    head.className="rebuilt-location-head "+(locationCategory(spot)==="town" ? "is-town" : "is-route");
    const icon=document.createElement("div");
    icon.className="rebuilt-location-icon";
    const typeSymbolSvg={
      Fire:`<svg viewBox="0 0 64 64" aria-hidden="true"><path d="M34 5c3 13-7 16-2 27 3-5 8-8 11-14 9 9 13 18 11 27-2 10-11 16-22 16S11 54 10 43c-1-10 5-18 14-27 0 9 2 13 6 16-2-10 5-16 4-27Z" fill="#f06b2b" stroke="#ffd27a" stroke-width="2.6"/><path d="M32 34c7 7 9 12 6 17-2 4-10 4-13 0-4-6 2-11 7-17Z" fill="#ffe0a0"/></svg>`,
      Water:`<svg viewBox="0 0 64 64" aria-hidden="true"><path d="M32 5C24 18 13 30 13 42a19 19 0 0 0 38 0C51 30 40 18 32 5Z" fill="#278bd0" stroke="#bce9ff" stroke-width="2.6"/><path d="M21 43c1 7 6 11 13 12" fill="none" stroke="#e4f7ff" stroke-width="3" stroke-linecap="round"/></svg>`,
      Electric:`<svg viewBox="0 0 64 64" aria-hidden="true"><path d="M37 4 14 36h16l-4 24 24-34H34l3-22Z" fill="#f6b51e" stroke="#fff0a6" stroke-width="2.6" stroke-linejoin="round"/></svg>`,
      Rock:`<svg viewBox="0 0 64 64" aria-hidden="true"><path d="m17 12 26-5 13 19-8 27-27 5L7 39Z" fill="#aaa8a2" stroke="#ece9df" stroke-width="2.6"/><path d="m17 12 12 14 14-19M29 26l19 27M29 26 7 39" fill="none" stroke="#5e5d59" stroke-width="2.4"/></svg>`,
      Ice:`<svg viewBox="0 0 64 64" aria-hidden="true"><g stroke="#dff7ff" stroke-width="3" stroke-linecap="round"><path d="M32 5v54M8 18l48 28M56 18 8 46"/><path d="m32 14-6-5m6 5 6-5m-6 41-6 5m6-5 6 5M16 23l-1-8m1 8-8 2m40 16 1 8m-1-8 8-2M48 23l1-8m-1 8 8 2M16 41l-1 8m1-8-8-2"/></g></svg>`,
      Fairy:`<svg viewBox="0 0 64 64" aria-hidden="true"><path d="m32 6 7 17 19 1-15 12 5 19-16-10-16 10 5-19L6 24l19-1Z" fill="#d47ac6" stroke="#ffe2fb" stroke-width="2.6"/></svg>`,
      Dark:`<svg viewBox="0 0 64 64" aria-hidden="true"><path d="M44 7A25 25 0 1 0 56 48 21 21 0 1 1 44 7Z" fill="#8b78a8" stroke="#f0e8ff" stroke-width="2.6"/></svg>`,
      Grass:`<svg viewBox="0 0 64 64" aria-hidden="true"><path d="M31 55V31" fill="none" stroke="#e9f7a8" stroke-width="3" stroke-linecap="round"/><path d="M31 37C14 35 12 19 13 10c13 2 23 9 22 21-1 4-2 5-4 6Z" fill="#9dbb45" stroke="#eef8a8" stroke-width="2.4"/><path d="M33 42c16-1 20-13 19-23-12 1-21 7-21 18 0 2 1 4 2 5Z" fill="#7e9f32" stroke="#eef8a8" stroke-width="2.4"/></svg>`
    };
    if(headerTownEmblems[spot.name]){
      icon.innerHTML='<img class="header-town-emblem" src="'+headerTownEmblems[spot.name]+'" alt="">';
    }else if(spot.type && typeSymbolSvg[spot.type]){
      icon.innerHTML='<span class="location-type-symbol">'+typeSymbolSvg[spot.type]+'</span>';
    }else{
      icon.innerHTML='<span class="location-type-symbol"><svg viewBox="0 0 64 64" aria-hidden="true"><circle cx="32" cy="32" r="12" fill="#e5ad3a" stroke="#ffe5a0" stroke-width="3"/><circle cx="32" cy="32" r="5" fill="#07131e"/></svg></span>';
    }

    const title=document.createElement("div");
    title.className="rebuilt-location-title";
    title.innerHTML="<h3></h3><p></p>";
    title.querySelector("h3").textContent=spot.name;
    const categoryLabel=locationCategory(spot)==="town" ? "Town / City" : "Route / Path";
    title.querySelector("p").innerHTML=
      '<span class="rebuilt-location-kind">'+categoryLabel+'</span>';

    const x=document.createElement("button");
    x.className="rebuilt-location-x";
    x.type="button";
    x.textContent="×";
    x.setAttribute("aria-label","Close location panel");
    x.addEventListener("click",closePanel);
    head.append(icon,title,x);

    const summary=document.createElement("div");
    summary.className="rebuilt-location-summary";
    summary.textContent=descriptions[spot.name] || "Lumen encounters recorded for this location in the Codex.";

    const heading=document.createElement("div");
    heading.className="rebuilt-lumen-heading";
    heading.innerHTML='<span>Lumen Found Here</span><b class="rebuilt-lumen-count">'+items.length+'</b>';

    const list=document.createElement("div");
    list.id="rebuilt-lumen-list";

    if(!items.length){
      const empty=document.createElement("div");
      empty.className="rebuilt-no-lumen";
      empty.textContent="No Lumen are currently recorded for this location in the Codex.";
      list.appendChild(empty);
    }else{
      items.forEach(original=>{
        const row=document.createElement("button");
        row.type="button";
        row.className="rebuilt-lumen-row";
        const thumb=original.querySelector(".side-thumb");
        const name=original.querySelector(".side-name");
        const types=original.querySelector(".side-types");

        if(thumb){
          const img=document.createElement("img");
          img.src=thumb.src;
          img.alt=name ? name.textContent.trim() : "";
          row.appendChild(img);
        }
        const info=document.createElement("div");
        info.className="rebuilt-lumen-info";
        const nm=document.createElement("div");
        nm.className="rebuilt-lumen-name";
        nm.textContent=name ? name.textContent.trim() : "Lumen";
        info.appendChild(nm);
        if(types){
          const t=document.createElement("div");
          t.className="rebuilt-lumen-types";
          t.innerHTML=types.innerHTML;
          info.appendChild(t);
        }
        row.appendChild(info);

        const meta=document.createElement("div");
        meta.className="rebuilt-lumen-meta";
        const probability=getMapEncounterProbability(original);
        if(probability!==null){
          const prob=document.createElement("span");
          prob.className="rebuilt-lumen-probability";
          prob.textContent=probability.toLocaleString(undefined,{maximumFractionDigits:6})+"%";
          prob.title="Encounter probability";
          meta.appendChild(prob);
        }
        const openHint=document.createElement("span");
        openHint.className="rebuilt-lumen-open-hint";
        openHint.textContent="View Codex ›";
        meta.appendChild(openHint);
        row.appendChild(meta);

        const lumenName=name ? name.textContent.trim() : "Lumen";
        row.title="Open "+lumenName+" in the Codex";
        row.setAttribute("aria-label","Open "+lumenName+" in the Codex");
        row.addEventListener("click",()=>openCodexItem(original));
        list.appendChild(row);
      });
    }

    panel.appendChild(head);

    const imageUrl=destinationImages[spot.name];
    if(imageUrl){
      const imgWrap=document.createElement("div");
      imgWrap.className="rebuilt-location-image";
      const destImg=document.createElement("img");
      destImg.src=imageUrl;
      destImg.alt=spot.name;
      destImg.loading="lazy";
      destImg.referrerPolicy="no-referrer";
      destImg.addEventListener("error",()=>imgWrap.classList.add("is-missing"));
      imgWrap.appendChild(destImg);
      panel.appendChild(imgWrap);
    }

    panel.append(summary,heading,list);

    const nav=document.createElement("div");
    nav.className="rebuilt-location-nav";

    const prev=document.createElement("button");
    prev.type="button";
    prev.className="rebuilt-location-nav-btn";
    prev.innerHTML='<span class="nav-arrow">‹</span><span><small>Previous</small><b></b></span>';
    const idx=currentNavIndex();
    const safeIdx=idx>=0 ? idx : 0;
    const prevIndex=(safeIdx-1+locationNavOrder.length)%locationNavOrder.length;
    prev.querySelector("b").textContent=locationNavOrder[prevIndex];
    prev.addEventListener("click",()=>openLocationByNavIndex(prevIndex));

    const next=document.createElement("button");
    next.type="button";
    next.className="rebuilt-location-nav-btn next";
    next.innerHTML='<span><small>Next</small><b></b></span><span class="nav-arrow">›</span>';
    const nextIndex=(safeIdx+1)%locationNavOrder.length;
    next.querySelector("b").textContent=locationNavOrder[nextIndex];
    next.addEventListener("click",()=>openLocationByNavIndex(nextIndex));

    nav.append(prev,next);
    panel.appendChild(nav);
  }

  function build(){
    const map=document.getElementById("lumena-world-map");
    if(!map || document.getElementById("rebuilt-map-ui")) return;

    const ui=document.createElement("div");
    ui.id="rebuilt-map-ui";
    ui.innerHTML=`
      <div class="rebuilt-map-header">
        <div class="rebuilt-map-brand">
          <div class="rebuilt-map-compass">✧</div>
          <div class="rebuilt-map-brand-text"><h2>LUMENA</h2><p>World Map</p></div>
        </div>
        <button class="rebuilt-map-close" id="rebuilt-map-close" type="button">CLOSE MAP <span>×</span></button>
      </div>
      <div class="rebuilt-map-body">
        <div class="rebuilt-map-left">
          <div class="rebuilt-map-viewport" id="rebuilt-map-viewport">
            <div class="rebuilt-map-zoom-controls" aria-label="Map zoom controls">
              <button type="button" id="rebuilt-map-zoom-out" aria-label="Zoom out">−</button>
              <button type="button" id="rebuilt-map-zoom-reset" aria-label="Reset zoom">100%</button>
              <button type="button" id="rebuilt-map-zoom-in" aria-label="Zoom in">+</button>
            </div>
            <div class="rebuilt-map-image-wrap" id="rebuilt-map-image-wrap">
              <img id="rebuilt-map-image" alt="Lumena World Map">
              <div class="rebuilt-route-cover">CLICK A GOLD<br>LOCATION CIRCLE<br>TO VIEW LUMEN</div>
              <div class="rebuilt-type-cover"></div>
            </div>
          </div>
        </div>
        <aside class="rebuilt-map-panel">
          <div class="rebuilt-panel-card panel-empty-state" id="rebuilt-panel-card">
            <div class="rebuilt-panel-empty">Click one of the gold circular markers on the map to view the Lumen recorded at that location.</div>
          </div>
        </aside>
      </div>
      <div class="rebuilt-map-footer">
        <div class="rebuilt-footer-left"><span><span class="rebuilt-footer-dot"></span>CLICK A LOCATION MARKER TO VIEW LUMEN</span></div>
        <div class="rebuilt-footer-right"><span><span class="rebuilt-footer-dot"></span>TOWN / CITY</span><span class="rebuilt-footer-route">ROUTE / PATH</span></div>
      </div>`;
    map.appendChild(ui);

    const image=ui.querySelector("#rebuilt-map-image");
    image.src=MAP_DATA;

    const wrap=ui.querySelector("#rebuilt-map-image-wrap");
    const hotspots=svg("svg",{
      id:"rebuilt-map-hotspots",
      viewBox:"0 0 1537 1023",
      preserveAspectRatio:"none",
      "aria-label":"Clickable Lumena location circles"
    });

    spots.forEach(spot=>{
      const g=svg("g",{
        class:"map-dot",
        tabindex:"0",
        role:"button",
        "aria-label":spot.name,
        "data-location":spot.name
      });
      g.appendChild(svg("circle",{class:"hit",cx:spot.x,cy:spot.y,r:(spot.hitR||spot.r)}));
      g.appendChild(svg("circle",{class:"ring",cx:spot.x,cy:spot.y,r:spot.r}));
      g.addEventListener("click",e=>{
        e.preventDefault();e.stopPropagation();showLocation(spot,g);
      });
      g.addEventListener("keydown",e=>{
        if(e.key==="Enter" || e.key===" "){
          e.preventDefault();showLocation(spot,g);
        }
      });
      hotspots.appendChild(g);
    });
    wrap.appendChild(hotspots);

    /* Mobile-friendly zoom/pan. Image + SVG hotspots transform together,
       so click targets stay perfectly aligned. */
    const viewport=ui.querySelector("#rebuilt-map-viewport");
    const zoomIn=ui.querySelector("#rebuilt-map-zoom-in");
    const zoomOut=ui.querySelector("#rebuilt-map-zoom-out");
    const zoomReset=ui.querySelector("#rebuilt-map-zoom-reset");
    let zoom=1, panX=0, panY=0;
    const MIN_ZOOM=1, MAX_ZOOM=3;

    function clampPan(){
      if(zoom<=1){ panX=0; panY=0; return; }
      const vr=viewport.getBoundingClientRect();
      const wr=wrap.getBoundingClientRect();
      const maxX=Math.max(0,(wr.width/zoom)*(zoom-1)/2);
      const maxY=Math.max(0,(wr.height/zoom)*(zoom-1)/2);
      panX=Math.max(-maxX,Math.min(maxX,panX));
      panY=Math.max(-maxY,Math.min(maxY,panY));
    }

    function applyMapTransform(){
      clampPan();
      /* Several older responsive-map rules use transform:none !important.
         Apply the live zoom transform with !important so those rules cannot
         cancel the zoom/pan controls. */
      wrap.style.setProperty("transform-origin","50% 50%","important");
      wrap.style.setProperty("transform",`translate(${panX}px,${panY}px) scale(${zoom})`,"important");
      wrap.classList.toggle("is-zoomed",zoom>1.001);
      zoomReset.textContent=Math.round(zoom*100)+"%";
      zoomOut.disabled=zoom<=MIN_ZOOM+.001;
      zoomIn.disabled=zoom>=MAX_ZOOM-.001;
    }

    function setZoom(next){
      const old=zoom;
      zoom=Math.max(MIN_ZOOM,Math.min(MAX_ZOOM,next));
      if(zoom===1){panX=0;panY=0;}
      else if(old>0){
        const ratio=zoom/old;
        panX*=ratio; panY*=ratio;
      }
      applyMapTransform();
    }

    zoomIn.addEventListener("click",()=>setZoom(zoom+.35));
    zoomOut.addEventListener("click",()=>setZoom(zoom-.35));
    zoomReset.addEventListener("click",()=>{zoom=1;panX=0;panY=0;applyMapTransform();});

    /* Mouse wheel zoom on desktop. */
    viewport.addEventListener("wheel",e=>{
      if(!e.ctrlKey && window.innerWidth>900) return;
      e.preventDefault();
      setZoom(zoom+(e.deltaY<0 ? .18 : -.18));
    },{passive:false});

    /* Pointer drag + two-finger pinch on touch devices. */
    const pointers=new Map();
    let dragStart=null, pinchStart=null;

    let didPan=false;
    viewport.addEventListener("pointerdown",e=>{
      /* Zoom buttons should remain ordinary controls. */
      if(e.target.closest && e.target.closest(".rebuilt-map-zoom-controls")) return;
      pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});
      didPan=false;
      if(pointers.size===1 && zoom>1 && !(e.target.closest && e.target.closest(".map-dot"))){
        dragStart={x:e.clientX,y:e.clientY,panX,panY};
        viewport.setPointerCapture?.(e.pointerId);
      }else if(pointers.size===2){
        const pts=[...pointers.values()];
        pinchStart={
          distance:Math.hypot(pts[0].x-pts[1].x,pts[0].y-pts[1].y),
          zoom
        };
        dragStart=null;
      }
    });

    viewport.addEventListener("pointermove",e=>{
      if(!pointers.has(e.pointerId)) return;
      pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});
      if(pointers.size===2 && pinchStart){
        const pts=[...pointers.values()];
        const d=Math.hypot(pts[0].x-pts[1].x,pts[0].y-pts[1].y);
        if(pinchStart.distance>0) setZoom(pinchStart.zoom*(d/pinchStart.distance));
      }else if(pointers.size===1 && dragStart && zoom>1){
        const dx=e.clientX-dragStart.x;
        const dy=e.clientY-dragStart.y;
        if(Math.abs(dx)>3 || Math.abs(dy)>3) didPan=true;
        panX=dragStart.panX+dx;
        panY=dragStart.panY+dy;
        applyMapTransform();
      }
    });

    /* Do not accidentally open a waypoint after dragging the zoomed map. */
    viewport.addEventListener("click",e=>{
      if(didPan){
        e.preventDefault();
        e.stopImmediatePropagation();
        didPan=false;
      }
    },true);

    function endPointer(e){
      pointers.delete(e.pointerId);
      if(pointers.size<2) pinchStart=null;
      if(pointers.size===0) dragStart=null;
    }
    viewport.addEventListener("pointerup",endPointer);
    viewport.addEventListener("pointercancel",endPointer);
    viewport.addEventListener("pointerleave",e=>{ if(e.pointerType!=="touch") endPointer(e); });

    window.addEventListener("resize",applyMapTransform,{passive:true});
    applyMapTransform();

    /* Final World Map consistency audit.
       This does not change encounter data; it verifies the live map configuration
       and reports problems in the browser console for maintenance. */
    function auditWorldMapConsistency(){
      const issues=[];
      const canonical=n=>navCanonicalName(String(n||"").trim());

      // 1. Every navigation location must exist exactly once in spots.
      locationNavOrder.forEach((name,index)=>{
        const matches=spots.filter(s=>canonical(s.name)===canonical(name));
        if(matches.length===0) issues.push(`Missing location #${index+1}: ${name}`);
        if(matches.length>1) issues.push(`Duplicate location definition: ${name} (${matches.length})`);
      });

      // 2. No unexpected locations should exist outside the approved order.
      spots.forEach(s=>{
        if(!locationNavOrder.some(n=>canonical(n)===canonical(s.name))){
          issues.push(`Location not in approved Previous/Next order: ${s.name}`);
        }
      });

      // 3. Hotspots must map one-to-one to map locations.
      const dots=[...document.querySelectorAll("#rebuilt-map-hotspots .map-dot")];
      const dotCounts={};
      dots.forEach(dot=>{
        const key=canonical(dot.dataset.location);
        dotCounts[key]=(dotCounts[key]||0)+1;
      });
      locationNavOrder.forEach(name=>{
        const count=dotCounts[canonical(name)]||0;
        if(count===0) issues.push(`Missing clickable hotspot: ${name}`);
        if(count>1) issues.push(`Duplicate clickable hotspot: ${name} (${count})`);
      });

      // 4. Encounter rows: no duplicate Lumen and probability must be descending.
      spots.forEach(spot=>{
        const seen=new Set();
        let last=Infinity;
        getItemsForSpot(spot).forEach(item=>{
          const id=String(item.dataset.id||"");
          const name=(item.querySelector(".side-name")?.textContent||id||"Unknown").trim();
          if(seen.has(id)) issues.push(`Duplicate Lumen in ${spot.name}: ${name}`);
          seen.add(id);
          const p=getMapEncounterProbability(item);
          if(p!==null){
            if(p>last+1e-12) issues.push(`Probability order issue in ${spot.name}: ${name} (${p}%)`);
            last=p;
          }
        });
      });

      // 5. Town/city emblem availability.
      spots.filter(s=>locationCategory(s)==="town").forEach(spot=>{
        if(!headerTownEmblems[spot.name]){
          issues.push(`Missing town/city emblem: ${spot.name}`);
        }
      });

      window.LumenaWorldMapAudit={
        checkedAt:new Date().toISOString(),
        locationCount:locationNavOrder.length,
        hotspotCount:dots.length,
        issues
      };

      if(issues.length){
        console.warn("[Lumena World Map] Consistency audit found "+issues.length+" issue(s):",issues);
      }else{
        console.info("[Lumena World Map] Consistency audit passed:",locationNavOrder.length+" locations checked.");
      }
      return window.LumenaWorldMapAudit;
    }

    /* Run once after the map DOM/hotspots are fully built. */
    setTimeout(auditWorldMapConsistency,0);

    ui.querySelector("#rebuilt-map-close").addEventListener("click",closeMap);
  }

  function openMap(){
    build();
    const map=document.getElementById("lumena-world-map");
    if(!map) return;
    map.classList.add("rebuilt-open");
    document.body.style.overflow="hidden";
  }

  function closeMap(){
    const map=document.getElementById("lumena-world-map");
    if(map) map.classList.remove("rebuilt-open");

    /* The rebuilt map is the only map mode now. Older map runtimes may have
       added this full-page class, so always clear it when leaving the map. */
    document.body.classList.remove("world-map-full-page","route-panel-open");
    document.documentElement.style.removeProperty("--route-panel-height");

    const toggle=document.getElementById("world-map-toggle");
    if(toggle) toggle.classList.remove("active");

    const results=document.getElementById("route-results");
    if(results) results.classList.remove("open");

    document.body.style.overflow="";

    /* Tell every location-highlight integration that the map genuinely closed.
       They keep their selected Lumen/location state in private closures, so
       clearing DOM classes alone is not enough. */
    window.dispatchEvent(new CustomEvent("lumena-map-closed"));
  }
  window.__rebuiltLumenaMapOpen=openMap;
  window.__rebuiltLumenaMapClose=closeMap;

  function install(){
    build();
    const toggle=document.getElementById("world-map-toggle");
    if(toggle){
      /* Replace all older map-button click behavior with the rebuilt overlay. */
      const replacement=toggle.cloneNode(true);
      toggle.parentNode.replaceChild(replacement,toggle);
      replacement.addEventListener("click",function(e){
        e.preventDefault();
        e.stopPropagation();
        openMap();
      });
    }
    /* Start hidden; the Codex remains normal until World Map is clicked. */
    closeMap();
  }

  if(document.readyState==="loading") document.addEventListener("DOMContentLoaded",install,{once:true});
  else install();
})();
